#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
#include <stdlib.h>

int main() {
    pid_t pid = fork();
    if (pid == 0) {
        printf("Child PID %d doing work...
", getpid());
        exit(42); // return code 42
    } else {
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            printf("Parent received exit code %d from child %d
", WEXITSTATUS(status), pid);
        }
    }
    return 0;
}

