#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
#include <stdlib.h>

int main() {
    pid_t pid1 = fork();
    if (pid1 == 0) {
        // Child A
        pid_t pid2 = fork();
        if (pid2 == 0) {
            printf("Grandchild PID %d, PPID %d
", getpid(), getppid());
        } else {
            printf("Child A PID %d created Grandchild PID %d
", getpid(), pid2);
        }
    } else {
        // Parent
        pid_t pid3 = fork();
        if (pid3 == 0) {
            printf("Child B PID %d, PPID %d
", getpid(), getppid());
        } else {
            printf("Parent PID %d created Child A PID %d and Child B PID %d
", getpid(), pid1, pid3);
        }
    }
    // Wait for all children to finish to avoid zombies
    while (wait(NULL) > 0) {}
    return 0;
}

